package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.node.NumericNode;
import com.fasterxml.jackson.databind.node.TextNode;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TreeTraversingParser#getLongValue
 */
public class TreeTraversingParser_getLongValue_TriageGen2Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }

    /**
     * Tests getLongValue when the current node is a valid Long NumericNode.
     */
    @Test
    public void testGetLongValue_Success() throws IOException {
        JsonNode root = JsonNodeFactory.instance.numberNode(123456789L);
        TreeTraversingParser parser = new TreeTraversingParser(root);

        // Move to the numeric node
        parser.nextToken();

        long value = parser.getLongValue();
        assertEquals(123456789L, value);
        parser.close();
    }

    /**
     * Tests getLongValue when the current node is a Double NumericNode.
     * Jackson's NumericNode.longValue() handles conversion.
     */
    @Test
    public void testGetLongValue_FromDouble() throws IOException {
        JsonNode root = JsonNodeFactory.instance.numberNode(123.45);
        TreeTraversingParser parser = new TreeTraversingParser(root);

        parser.nextToken();

        long value = parser.getLongValue();
        assertEquals(123L, value);
        parser.close();
    }

    /**
     * Tests getLongValue when the current node is a BigInteger NumericNode.
     */
    @Test
    public void testGetLongValue_FromBigInteger() throws IOException {
        // Large number that fits in long
        JsonNode root = JsonNodeFactory.instance.numberNode(new java.math.BigInteger("9223372036854775807"));
        TreeTraversingParser parser = new TreeTraversingParser(root);

        parser.nextToken();

        long value = parser.getLongValue();
        assertEquals(Long.MAX_VALUE, value);
        parser.close();
    }

    /**
     * Tests getLongValue when the current node is NOT a NumericNode (e.g., a TextNode).
     * This should trigger a ClassCastException because of the (NumericNode) cast.
     */
    @Test(expected = ClassCastException.class)
    public void testGetLongValue_NotANumericNode() throws IOException {
        JsonNode root = JsonNodeFactory.instance.textNode("not a number");
        TreeTraversingParser parser = new TreeTraversingParser(root);

        parser.nextToken();

        // This should throw ClassCastException: TextNode cannot be cast to NumericNode
        parser.getLongValue();
        parser.close();
    }

    /**
     * Tests getLongValue when there is no current node (EOF/Null).
     * Depending on implementation of currentNumericNode(), it might throw JsonParseException or NullPointerException.
     */
    @Test(expected = RuntimeException.class)
    public void testGetLongValue_NoCurrentNode() throws IOException {
        JsonNode root = JsonNodeFactory.instance.objectNode();
        TreeTraversingParser parser = new TreeTraversingParser(root);

        // We don't call nextToken(), so currentNumericNode might return null or throw exception
        parser.getLongValue();
        parser.close();
    }

    /**
     * Tests getLongValue when the current node is a null node.
     */
    @Test(expected = ClassCastException.class)
    public void testGetLongValue_NullNode() throws IOException {
        JsonNode root = JsonNodeFactory.instance.nullNode();
        TreeTraversingParser parser = new TreeTraversingParser(root);

        parser.nextToken();

        // NullNode is not a NumericNode
        parser.getLongValue();
        parser.close();
    }
}
